open.example:
// client
const { Web, Controls } = kcds.ui;

const shop = Web.open('kcds://resources/shop_menu/ui/index.html', { width: 800, height: 600, focus: true });
Controls.showCursor();

Web.on(shop, 'buy', (item) => {
  kcds.core.Events.toServer('menuBuy', item);
});
Web.emit(shop, 'gold', { amount: 120 });

