navigate.example:
// client: reload a page that failed, after a moment; only the main frame counts
const { Web } = kcds.ui;

const chatView = Web.open('https://chat.example.com/', { width: 600, height: 400 });

kcds.core.Events.on('webViewFailed', (failure) => {
  if (failure.viewId !== chatView || !failure.isMainFrame) {
    return;
  }
  console.warn(`chat did not load: ${failure.description} (${failure.errorCode})`);
  setTimeout(() => Web.navigate(chatView, failure.url), 3000);
});

navigate.exampleCs:
// client: reload a page that failed, after a moment; only the main frame counts

var chatView = Web.Open("https://chat.example.com/", new { width = 600, height = 400 });

Events.On("webViewFailed", (JsValue failure) =>
{
    if (failure["viewId"].AsNumber() != chatView || !failure["isMainFrame"])
    {
        return;
    }
    Log.Warn($"chat did not load: {failure["description"]} ({failure["errorCode"]})");
    Timers.SetTimeout(() => Web.Navigate(chatView, failure["url"]), 3000);
});

