nearestWorldScreen.example:
// client: F8 works the screen in front of the player
const { Web, Key } = kcds.ui;
Key.bind('f8', () => {
  const me = kcds.players.LocalPlayer?.position;
  const screen = me ? Web.nearestWorldScreen(me, 15) : null;
  if (screen !== null) {
    Web.focus(screen, true);
  }
});

nearestWorldScreen.exampleCs:
// client: F8 works the screen in front of the player
Key.Bind("f8", () =>
{
    var me = LocalPlayer.Current?.Position;
    if (me == null)
    {
        return;
    }
    var screen = Web.NearestWorldScreen(me, 15);
    if (!screen.IsNull)
    {
        Web.Focus(screen, true);
    }
});

